constexpr long long polynomial_hash(const char* str, int len) {
    long long hash = 0;
    constexpr long long base = 31;
    constexpr long long mod = 1000000007;
    for (int i = 0; i < len; ++i) {
        hash = (hash * base + str[i]) % mod;
    }
    return hash;
}

