template<typename T>
T gcd(T a, T b) {
    while (b != 0) {
        T temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

template<typename T>
T lcm(T a, T b) {
    return (a / gcd(a, b)) * b;
}

