#include <stdio.h>
#include <math.h>
#define HEAP_SIZE 8

struct PacketHeader {
    unsigned int type : 3;
    unsigned int priority : 4;
    unsigned int reserved : 1;
    unsigned int flags : 8;
};

int heap[HEAP_SIZE];
int heap_count = 0;

void heap_push(int value) {
    if (heap_count >= HEAP_SIZE) return;
    int i = heap_count++;
    heap[i] = value;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] >= heap[i]) break;
        int temp = heap[parent];
        heap[parent] = heap[i];
        heap[i] = temp;
        i = parent;
    }
}

int heap_pop() {
    if (heap_count <= 0) return 0;
    int result = heap[0];
    heap[0] = heap[--heap_count];
    int i = 0;
    while (1) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        int largest = i;
        if (left < heap_count && heap[left] > heap[largest])
            largest = left;
        if (right < heap_count && heap[right] > heap[largest])
            largest = right;
        if (largest == i) break;
        int temp = heap[i];
        heap[i] = heap[largest];
        heap[largest] = temp;
        i = largest;
    }
    return result;
}

int main() {
    struct PacketHeader pkt1 = {0};
    pkt1.type = 5;
    pkt1.priority = 12;
    pkt1.flags = 0xAB;

    struct PacketHeader pkt2 = {0};
    pkt2.type = 3;
    pkt2.priority = 7;
    pkt2.flags = 0x3C;

    int mask = 0xF0;
    int masked_flags1 = pkt1.flags & mask;
    int masked_flags2 = pkt2.flags & mask;

    int xor_result = masked_flags1 ^ masked_flags2;
    int shifted_priority1 = pkt1.priority << 1;
    int shifted_priority2 = pkt2.priority >> 1;

    double exp_val = pow(2.0, 3.0);
    int log_val = (int)log2((double)xor_result);

    heap_push(shifted_priority1);
    heap_push(shifted_priority2);
    heap_push(log_val);
    heap_push((int)exp_val);

    int sum_popped = 0;
    int iterations = 0;
    while (heap_count > 0 && iterations < 3) {
        sum_popped += heap_pop();
        iterations++;
    }

    int final_priority = sum_popped & 0xFF;
    printf("Result: %d\n", final_priority);
    return 0;
}

#include <iostream>
#include <vector>
#include <bitset>
#include <queue>

class DNAEncoder {
private:
    std::vector<int> encodedSequence;

public:
    DNAEncoder(const std::string& dna) {
        for (char c : dna) {
            switch(c) {
                case 'A': encodedSequence.push_back(0); break;
                case 'T': encodedSequence.push_back(1); break;
                case 'G': encodedSequence.push_back(2); break;
                case 'C': encodedSequence.push_back(3); break;
            }
        }
    }

    std::vector<int> getEncoded() const { return encodedSequence; }

    // Overload XOR operator for mutation simulation
    DNAEncoder operator^(const std::vector<int>& mask) const {
        DNAEncoder result("");
        for (size_t i = 0; i < encodedSequence.size(); ++i) {
            int maskedValue = encodedSequence[i] ^ mask[i % mask.size()];
            result.encodedSequence.push_back(maskedValue);
        }
        return result;
    }

    // Convert encoded sequence to decimal
    int toDecimal() const {
        int decimal = 0;
        for (int code : encodedSequence) {
            decimal = (decimal << 2) | code;
        }
        return decimal;
    }
};

int main() {
    // Original DNA sequence: ATGCAT
    DNAEncoder dna("ATGCAT");

    // Mutation mask: 101 (binary) = 5 (decimal)
    std::vector<int> mask = {1, 0, 1};

    // Apply mutation simulation
    DNAEncoder mutated = dna ^ mask;

    // Priority queue to process mutations in order
    std::priority_queue<int> mutationHeap;
    auto mutatedSequence = mutated.getEncoded();

    for (int code : mutatedSequence) {
        mutationHeap.push(code);
    }

    // Process mutations
    int finalCode = 0;
    int position = 0;
    std::vector<int> processedCodes(mutatedSequence.size());

    while (!mutationHeap.empty()) {
        processedCodes[position++] = mutationHeap.top();
        mutationHeap.pop();
    }

    // Reconstruct sequence with processed codes
    DNAEncoder finalDNA("");
    for (int code : processedCodes) {
        finalDNA = DNAEncoder("") ^ std::vector<int>(1, code);
        finalCode = (finalCode << 2) | code;
    }

    std::cout << "Result: " << finalCode << std::endl;
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct mem_block {
    int size;
    int status; // 0 = free, 1 = allocated
    struct mem_block* next;
    struct mem_block* prev;
};

volatile int op_counter = 0;

void insert_block(struct mem_block** head, int size) {
    struct mem_block* new_block = (struct mem_block*)malloc(sizeof(struct mem_block));
    new_block->size = size;
    new_block->status = 0;
    new_block->next = *head;
    new_block->prev = NULL;
    if (*head != NULL) (*head)->prev = new_block;
    *head = new_block;
}

int count_free_blocks(struct mem_block* head) {
    int count = 0;
    while (head != NULL) {
        if (head->status == 0) count++;
        head = head->next;
    }
    return count;
}

int main() {
    struct mem_block* head = NULL;

    // Initialize free list
    insert_block(&head, 64);
    insert_block(&head, 32);
    insert_block(&head, 128);
    insert_block(&head, 16);

    int request_size = 40;
    struct mem_block* current = head;
    int final_block_count = 0;

    while (current != NULL) {
        op_counter++;
        int action = (current->size ^ request_size) & 0x3; // Bitwise XOR and mask

        switch(action) {
            case 0: // Exact fit
                current->status = 1;
                break;
            case 1: // Split required
                if (current->size > request_size + 16) {
                    struct mem_block* new_block = (struct mem_block*)malloc(sizeof(struct mem_block));
                    new_block->size = current->size - request_size;
                    new_block->status = 0;
                    new_block->next = current->next;
                    new_block->prev = current;
                    if (current->next) current->next->prev = new_block;
                    current->next = new_block;
                    current->size = request_size;
                    current->status = 1;
                }
                break;
            case 2: // Merge with next if both free
                if (current->next && current->next->status == 0 && current->status == 0) {
                    current->size += current->next->size;
                    struct mem_block* temp = current->next;
                    current->next = temp->next;
                    if (temp->next) temp->next->prev = current;
                    free(temp);
                }
                break;
            default: // No operation
                break;
        }

        current = current->next;
    }

    final_block_count = count_free_blocks(head);
    printf("Result: %d\n", final_block_count);

    // Cleanup
    while (head != NULL) {
        struct mem_block* temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}

