class VendingMachine {
public:
    struct Change {
        int quarters = 0;
        int dimes = 0;
        int nickels = 0;
        int pennies = 0;
    };

    constexpr static Change calculateChange(int amount) {
        Change change;
        change.quarters = amount / 25;
        amount %= 25;
        change.dimes = amount / 10;
        amount %= 10;
        change.nickels = amount / 5;
        amount %= 5;
        change.pennies = amount;
        return change;
    }
};

