from collections import deque
import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Key derivation function using lambda and closure
transform_ops = [
    lambda x: x * 2 if x % 2 == 0 else x + 3,
    lambda x: fibonacci(x % 10) if x > 5 else x,
    lambda x: x ^ (x >> 1) if x & 1 else x | (x << 1)
]

# Initialization vector
init_vector = 12345

# Prime factorization step
factors = []
num = init_vector
divisor = 2
while divisor * divisor <= num:
    if num % divisor == 0:
        factors.append(divisor)
        num //= divisor
    else:
        divisor += 1
if num > 1:
    factors.append(num)

# Stack-based transformation
stack = deque()
for factor in factors:
    if is_prime(factor):
        stack.append(factor)
    else:
        if stack:
            stack.pop()

# LCM calculation of remaining stack elements
lcm_result = 1
while stack:
    element = stack.popleft()
    lcm_result = lcm(lcm_result, element)

# Apply transformation operations
derived_key = lcm_result
for op in transform_ops:
    derived_key = op(derived_key)

# Final adjustment based on logical conditions
if derived_key > 100 and not (derived_key & 1):
    derived_key = derived_key >> 2
elif derived_key <= 100 or (derived_key & 1):
    derived_key = derived_key << 1

print(f"Result: {derived_key}")

#include <iostream>
#include <vector>
#include <algorithm>
#include <optional>

class PackageLoader {
private:
    std::vector<std::pair<int, int>> packages; // {priority, weight}
    int truckCapacity;
    int minLoadRequirement;
    int loadedPackages;

    bool tryGreedyLoad() {
        // Sort by priority descending
        std::sort(packages.begin(), packages.end(), 
                  [](const auto& a, const auto& b) { return a.first > b.first; });

        int currentWeight = 0;
        loadedPackages = 0;

        for (const auto& pkg : packages) {
            if (currentWeight + pkg.second <= truckCapacity) {
                currentWeight += pkg.second;
                loadedPackages++;
            }
            // Early return if we've met minimum requirement
            if (currentWeight >= minLoadRequirement && 
                (packages.size() <= 5 || loadedPackages >= 3)) {
                return true;
            }
        }

        return currentWeight >= minLoadRequirement;
    }

    std::optional<int> backtrackLoad(int index, int currentWeight, int count) {
        // Base cases
        if (currentWeight >= minLoadRequirement && currentWeight <= truckCapacity) {
            return count;
        }
        if (index >= static_cast<int>(packages.size()) || 
            currentWeight > truckCapacity) {
            return std::nullopt;
        }

        // Try including current package
        auto withPackage = backtrackLoad(index + 1, 
                                        currentWeight + packages[index].second, 
                                        count + 1);

        // Try excluding current package (short-circuit if withPackage is valid)
        std::optional<int> withoutPackage;
        if (!withPackage.has_value() || withPackage.value() > count) {
            withoutPackage = backtrackLoad(index + 1, currentWeight, count);
        }

        // Return better solution
        if (withPackage.has_value() && withoutPackage.has_value()) {
            return std::min(withPackage.value(), withoutPackage.value());
        } else if (withPackage.has_value()) {
            return withPackage;
        } else {
            return withoutPackage;
        }
    }

public:
    PackageLoader(int capacity, int minLoad) 
        : truckCapacity(capacity), minLoadRequirement(minLoad), loadedPackages(0) {}

    void addPackage(int priority, int weight) {
        packages.push_back({priority, weight});
    }

    int executeLoading() {
        // Try greedy approach first
        if (tryGreedyLoad()) {
            return loadedPackages;
        }

        // If greedy fails, use backtracking
        auto result = backtrackLoad(0, 0, 0);
        if (result.has_value()) {
            loadedPackages = result.value();
            return loadedPackages;
        }

        // If both fail, load nothing
        loadedPackages = 0;
        return 0;
    }
};

int main() {
    PackageLoader loader(100, 70);

    // Add packages: {priority, weight}
    loader.addPackage(5, 30);
    loader.addPackage(8, 25);
    loader.addPackage(3, 20);
    loader.addPackage(7, 15);
    loader.addPackage(6, 35);
    loader.addPackage(4, 10);
    loader.addPackage(9, 40);

    int loadedPackages = loader.executeLoading();

    std::cout << "Result: " << loadedPackages << std::endl;
    return 0;
}

#include <stdio.h>
#include <string.h>

struct PacketHeader {
    unsigned int version : 4;
    unsigned int ihl : 4;
    unsigned int ttl : 8;
    unsigned int protocol : 8;
    unsigned int checksum : 16;
};

union HeaderConverter {
    struct PacketHeader fields;
    unsigned int raw;
};

unsigned int (*checksum_func)(unsigned int, unsigned int);

unsigned int compute_checksum(unsigned int a, unsigned int b) {
    return (a ^ b) + (a & b);
}

unsigned int greedy_parser(const char* token_stream) {
    unsigned int state = 0;
    int i = 0;
    while (token_stream[i] != '\0') {
        if (token_stream[i] == '1') {
            state = (state << 1) | 1;
        } else if (token_stream[i] == '0') {
            state = state << 1;
        } else {
            state += token_stream[i] - '0';
        }
        i++;
    }
    return state;
}

int main() {
    volatile unsigned int header_data = 0x4500003c;
    union HeaderConverter converter;
    converter.raw = header_data;

    checksum_func = compute_checksum;

    const char* tokens = "11010100111000101010111100001111";
    unsigned int parsed_value = greedy_parser(tokens);

    unsigned int field_sum = converter.fields.version + 
                             converter.fields.ihl + 
                             converter.fields.ttl + 
                             converter.fields.protocol;

    unsigned int final_checksum = checksum_func(field_sum, parsed_value);

    printf("Result: %u\n", final_checksum);
    return 0;
}

