    int operation_indices[] = {0, 1, 2, 0}; // 0=add, 1=xor, 2=mul

    int final_checksum = recursive_checksum(firmware_segments, operation_indices, FIRMWARE_SEGMENTS);
    printf("Result: %d\n", final_checksum);
