public:
    explicit VaultHasher(uint32_t seed) : state(seed) {}

    void update(char c) {
        uint32_t val = static_cast<uint32_t>(c);
        state ^= (val << 3) & 0xFFFFFFF0;
        state = (state >> 1) | (state << 31);
        state &= 0xFFFFFFFF;
    }

    uint32_t getHash() const { return state; }
};

