void calibrate_temperatures(struct temp_data* data) {
    for (int i = 0; i < data->count; i++) {
        union converter cvt;
        cvt.f_val = data->raw_values[i] * CALIBRATION_FACTOR;
        data->calibrated_values[i] = cvt.f_val;
