float calculate_median(float arr[], int n) {
    // Simple bubble sort for small arrays
    for (int i = 0; i < n-1; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                float temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }

    if (n % 2 == 0) {
        return (arr[n/2-1] + arr[n/2]) / 2.0;
    } else {
        return arr[n/2];
    }
}

