        {10, 20, 10, 30, 10, 40, 50, 60, 70, 80},
        {5, 15, 25, 5, 35, 5, 45, 55, 65, 75},
        {100, 200, 100, 300, 400, 500, 600, 700, 800, 900}
    };

    LinkedListNode* head = NULL;
