    for (int i = 0; i < 3; i++) {
        init_hash();
        for (int j = 0; j < 10; j++) {
            insert(device_readings[i][j]);
        }
        int anomaly_count = get_anomaly_count();
        LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
        new_node->anomaly_count = anomaly_count;
        new_node->next = head;
        head = new_node;
        clear_hash();
    }

    LinkedListNode* current = head;
    while (current != NULL) {
