int binary_search_code(const std::vector<std::pair<int, std::string>>& codes, const std::string& target) {
    int left = 0;
    int right = codes.size() - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (codes[mid].second == target) {
            return codes[mid].first;
        }
        if (codes[mid].second < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

int main() {
