    for (char bit : encoded_message) {
        current_code += bit;
        char decoded_char = binary_search_code(decoding_vector, current_code);
        if (decoded_char != -1) {
            decoded_length++;
            current_code = "";
        }
    }

    // END OF DECODING PROCESS

    std::cout << "Result: " << decoded_length << std::endl;
    return 0;
}

