int apply_window(int sample) {
    return sample & 0xFF; // Mask to 8-bit
}

int scale_amplitude(int sample) {
    int fib_factor = fibonacci(6); // 8
    return (sample * fib_factor) >> 3; // Divide by 8 using bit shift
}

