    meta_tags = ['REV', 'CMP', 'SHF', 'REP2', 'BRK', 'CMP']
    transformed = processor.process(dna_seq, meta_tags)
    checksum = processor.compute_checksum(transformed)
    print(f"Result: {checksum}")

