        }

        // Update checksum using modular addition
        checksum = (checksum + temp) % MODULUS;

        // Apply bitwise AND with index for even positions
        if ((i & 1) == 0) {
            checksum &= (0xFF >> (i/2));  // Progressive masking
        }
    }

    // Final adjustment
