                telemetryChecksum += 10;
                break;
            case 1:
                telemetryChecksum -= 3;
                break;
            case 2:
                telemetryChecksum *= 2;
                break;
            default:
                if (result > 2) {
                    telemetryChecksum += 5;
                }
                return 0; // Early exit simulation (won't execute here)
        }
        index++;
    }

    // Final adjustment
    if (telemetryChecksum % 2 == 0) {
        telemetryChecksum /= 2;
