    const unsigned int obstacleMap = 0b10101010;
    const unsigned int pathFlags = 0b11001100;

    // Check if path is clear using short-circuit evaluation
    bool pathClear = (obstacleMap & pathFlags) == 0 && (pathCombinations > 0);

