#define EVEN_PARITY(x) ((__builtin_popcount(x) % 2) == 0)

struct ComponentState {
    unsigned int active : 1;
    unsigned int powered : 1;
    unsigned int error : 1;
    unsigned int reserved : 5;
};

union SignalData {
    struct ComponentState bits;
    unsigned char raw;
};

struct TreeNode {
    union SignalData data;
    struct TreeNode* left;
    struct TreeNode* right;
};

unsigned int factorial(unsigned int n) {
    return (n <= 1) ? 1 : n * factorial(n - 1);
}

// C(6,2) = 6!/(2!*(6-2)!) = 15
unsigned int combinations_6_2() {
    return factorial(6) / (factorial(2) * factorial(4));
}

// P(5,3) = 5!/(5-3)! = 60
unsigned int permutations_5_3() {
    return factorial(5) / factorial(2);
}

struct TreeNode* create_node(unsigned char value) {
    struct TreeNode* node = malloc(sizeof(struct TreeNode));
    node->data.raw = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int main() {
    // Create a complete binary tree of depth 3
    struct TreeNode* root = create_node(0);
    root->left = create_node(0b00000101);  // 5
    root->right = create_node(0b00000011); // 3
    root->left->left = create_node(0b00000110);  // 6
    root->left->right = create_node(0b00000001); // 1
    root->right->left = create_node(0b00000100); // 4
    root->right->right = create_node(0b00000010); // 2

    // Propagate signals up the tree using XOR
    root->left->data.raw = root->left->left->data.raw ^ root->left->right->data.raw;
    root->right->data.raw = root->right->left->data.raw ^ root->right->right->data.raw;
    root->data.raw = root->left->data.raw ^ root->right->data.raw;

    // Count combinations/permutations based on root parity
    int propagation_result = EVEN_PARITY(root->data.raw) ? combinations_6_2() : permutations_5_3();

    // Clean up memory
    free(root->left->left);
    free(root->left->right);
    free(root->right->left);
    free(root->right->right);
    free(root->left);
    free(root->right);
    free(root);

    printf("Result: %d\n", propagation_result);
    return 0;
}

#include <iostream>

class RoboticArm {
private:
    int position;
    int state;
    int fib_prev;
    int fib_curr;

public:
    RoboticArm() : position(0), state(0), fib_prev(0), fib_curr(1) {}

    // Operator overloading for movement
    RoboticArm& operator+=(int increment) {
        position += increment;
        return *this;
    }

    // Move constructor
    RoboticArm(RoboticArm&& other) noexcept 
        : position(other.position), state(other.state), 
          fib_prev(other.fib_prev), fib_curr(other.fib_curr) {
        other.position = 0;
        other.state = 0;
    }

    int get_position() const { return position; }
    int get_state() const { return state; }

    void update_fibonacci() {
        int temp = fib_curr;
        fib_curr = fib_prev + fib_curr;
        fib_prev = temp;
    }

    int get_fibonacci() const { return fib_curr; }

    void transition_state(bool sensor_A, bool sensor_B) {
        // State transition logic using boolean operations
        if ((sensor_A && !sensor_B) || (state == 0)) {
            state = 1;
        } else if ((!sensor_A && sensor_B) && state != 2) {
            state = 2;
        } else if (!(sensor_A || sensor_B)) {
            state = 3;
        } else {
            state = 0;
        }
    }
};

int main() {
    RoboticArm arm;
    int final_position = 0;

    // Controller sequence
    for (int i = 0; i < 5; ++i) {
        bool sensor_A = (i % 2 == 0);
        bool sensor_B = (i % 3 == 0);

        arm.transition_state(sensor_A, sensor_B);
        arm.update_fibonacci();

        // Move based on state and fibonacci value
        if (arm.get_state() == 1 || arm.get_state() == 2) {
            arm += arm.get_fibonacci();
        } else if (arm.get_state() == 3) {
            arm += (arm.get_fibonacci() * 2);
        }
    }

    final_position = arm.get_position();
    std::cout << "Result: " << final_position << std::endl;
    return 0;
}

